 69	/// A reference to a capture group in some text.
 70	///
 71	/// e.g., `$2`, `$foo`, `${foo}`.
 72	#[derive(Clone, Copy, Debug, Eq, PartialEq)]
 73	enum Ref<'a> {
 74	    Named(&'a str),
 75	    Number(usize),
 76	}
